ALTER TABLE "ai_credit_reservations" ADD CONSTRAINT "ai_credit_reservations_terminal_state" CHECK (("ai_credit_reservations"."state" = 'active' and "ai_credit_reservations"."settled_at" is null and "ai_credit_reservations"."measurement" is null and "ai_credit_reservations"."charged_credits" is null and "ai_credit_reservations"."measured_credits" is null) or ("ai_credit_reservations"."state" = 'released' and "ai_credit_reservations"."settled_at" is not null and "ai_credit_reservations"."measurement" is null and "ai_credit_reservations"."charged_credits" = 0 and "ai_credit_reservations"."measured_credits" is null) or ("ai_credit_reservations"."state" = 'settled' and "ai_credit_reservations"."settled_at" is not null and "ai_credit_reservations"."measurement" is not null and "ai_credit_reservations"."charged_credits" between 0 and 9007199254740991 and (("ai_credit_reservations"."measurement" = 'provider_reported' and "ai_credit_reservations"."measured_credits" between 0 and 9007199254740991) or ("ai_credit_reservations"."measurement" in ('estimated', 'unmetered', 'speech_success', 'speech_no_charge') and "ai_credit_reservations"."measured_credits" is null) or ("ai_credit_reservations"."measurement" = 'technical_failure' and "ai_credit_reservations"."measured_credits" is null and "ai_credit_reservations"."charged_credits" = 0))));--> statement-breakpoint
ALTER TABLE "dictionary_generation_jobs" ADD CONSTRAINT "dictionary_generation_jobs_ai_credit_state" CHECK (("dictionary_generation_jobs"."selected_execution_snapshot"->>'actionAccountingVersion' = '1' and "dictionary_generation_jobs"."ai_credit_accounted" = false and "dictionary_generation_jobs"."ai_credit_reservation_id" is null) or ("dictionary_generation_jobs"."ai_credit_accounted" = false and "dictionary_generation_jobs"."ai_credit_input_credits_per_million_tokens" is null and "dictionary_generation_jobs"."ai_credit_max_credits_per_attempt" is null and "dictionary_generation_jobs"."ai_credit_output_credits_per_million_tokens" is null and "dictionary_generation_jobs"."ai_credit_policy_mode" is null and "dictionary_generation_jobs"."ai_credit_pricing_revision" is null and "dictionary_generation_jobs"."ai_credit_provider_dispatched_at" is null and "dictionary_generation_jobs"."ai_credit_reservation_id" is null) or ("dictionary_generation_jobs"."ai_credit_accounted" = true and "dictionary_generation_jobs"."ai_credit_input_credits_per_million_tokens" >= 0 and "dictionary_generation_jobs"."ai_credit_max_credits_per_attempt" > 0 and "dictionary_generation_jobs"."ai_credit_output_credits_per_million_tokens" >= 0 and "dictionary_generation_jobs"."ai_credit_pricing_revision" = 1 and ("dictionary_generation_jobs"."ai_credit_policy_mode" is null or "dictionary_generation_jobs"."ai_credit_policy_mode" in ('limited', 'unlimited')) and ("dictionary_generation_jobs"."ai_credit_provider_dispatched_at" is null or "dictionary_generation_jobs"."ai_credit_policy_mode" is not null)));